package net.civeira.phylax.features.access.userwebauthncredential.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.access.userwebauthncredential.domain.UserWebauthnCredential;
import net.civeira.phylax.features.access.userwebauthncredential.domain.event.UserWebauthnCredentialEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class UserWebauthnCredentialEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<UserWebauthnCredentialEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final UserWebauthnCredential entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
